import csv
with open('outputs/t01_selected_indicators.csv', 'r', encoding='utf-8', newline='') as f:
    reader = csv.DictReader(f)
    selected = {row['indicator_id']: row['indicator_name'] for row in reader}

with open('outputs/t02_eurostat_raw.csv', 'r', encoding='utf-8', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ind_id = row['indicator_id']
        ind_name = row['indicator_name']
        if ind_id in selected:
            if selected[ind_id] != ind_name:
                print(f'Mismatch for {ind_id}:')
                print(f'  Selected: {selected[ind_id]}')
                print(f'  Output: {ind_name}')
                break
    else:
        print('All indicator names match selected indicators file')
""}

